exercises.solution:
package main

import "fmt"

func main() {
    adder := makeAdder()
    fmt.Println(adder(5))
    fmt.Println(adder(10))
}

func makeAdder() func(int) int {
    sum := 0
    return func(x int) int {
        sum += x
        return sum
    }
}
